export{ModalEmpresaCtrl};function ModalEmpresaCtrl($scope,$uibModalInstance,mS,tS,fS,params){function onInit(){params&&params.idEmpresa>0&&($scope.tipoRegistro=2,$scope.data=params)}$scope.tipoRegistro=1,$scope.data={},onInit(),$scope.copiarRazonSocial=function(){$scope.data.razonSocial||($scope.data.nombreComercial=$scope.data.razonSocial)},$scope.saveAndUpdate=function(){if(!$scope.data.ruc)return void tS.toastr("warning","Ingrese Número de RUC");if($("#ruc").hasClass("is-invalid"))return void tS.toastr("warning","Ingrese Número de Correctamente");if(13!==$scope.data.ruc.toString().length)return void tS.toastr("warning","Número de Ruc tiene que tener 13 dígitos");if(!$scope.data.razonSocial)return void tS.toastr("warning","Ingrese campo Razon Social");if(!$scope.data.nombreComercial)return void tS.toastr("warning","Ingrese campo Nombre Comercia");const URL=1===$scope.tipoRegistro?"/Empresa/Post":"/Empresa/Put?id="+$scope.data.idEmpresa;showLoader(),mS.getData("post",URL,$scope.data).then(response=>{if("0"===response.id)return hideLoader(),void tS.toastr("warning",response.message);"1"===response.id&&(hideLoader(),tS.toastr("success",response.message,response.titleSms),$uibModalInstance.close(response))})},$scope.closeModal=function(){$uibModalInstance.close()}}ModalEmpresaCtrl.$inject=["$scope","$uibModalInstance","mainService","toastService","formulario","params"];